def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_requirements = []
    urgent_opp = 0
    rich_opp = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if isinstance(prev, dict) else None
            if bid is not None:
                prev_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    total_req = WATER_REQ
    for r in opp_requirements:
        total_req += r

    scarcity = float(total_req) / max(1.0, float(supply))
    high_supply = supply >= 22
    low_supply = supply <= 17

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1
    if low_supply:
        danger += 1
    if scarcity > 2.5:
        danger += 2
    elif scarcity > 2.0:
        danger += 1

    if danger >= 5:
        bid = max(0.92 * DAILY_SALARY, avg_prev * 0.92, highest_prev * 0.88)
    elif danger >= 3:
        bid = max(0.72 * DAILY_SALARY, avg_prev * 0.62, highest_prev * 0.58)
    else:
        if high_supply:
            bid = max(18.0, avg_prev * 0.18)
        elif supply >= 19:
            bid = max(26.0, avg_prev * 0.24)
        else:
            bid = max(34.0, avg_prev * 0.32)

    if urgent_opp >= 2:
        bid += 6.0
    elif urgent_opp == 1:
        bid += 3.0

    if rich_opp >= 2 and not high_supply:
        bid += 4.0

    if highest_prev >= 145 and danger <= 2:
        bid = min(bid, highest_prev * 0.35)
    elif highest_prev >= 130 and high_supply:
        bid = min(bid, highest_prev * 0.30)

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.85)
    else:
        reserve_target = 0.0
        if hp >= 6 and no_water_days == 0:
            reserve_target = DAILY_SALARY * 1.2
        elif hp >= 4:
            reserve_target = DAILY_SALARY * 0.7
        max_spend = max(0.0, budget - reserve_target)
        if max_spend > 0:
            bid = min(bid, max_spend)

    if danger >= 5:
        bid = max(bid, min(budget, 58.0))
    elif danger >= 3:
        bid = max(bid, min(budget, 42.0))

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If no opponents, bid minimally to save budget
    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    # Critical HP: Bid aggressively to survive
    if my_status['hp'] <= 2:
        # Bid significantly higher than salary, also scale up as days pass
        # This ensures survival in critical moments, potentially using accumulated budget.
        aggressive_bid = DAILY_SALARY * 1.3 + (EPISODE_DAYS - day_context['day']) * 5.0
        return max(1.0, min(my_status['budget'], aggressive_bid))

    # Strategy for healthy HP, reacting to opponents' previous bids
    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    # A moderate base bid if no significant previous bids or first day
    base_bid = DAILY_SALARY * 0.75

    if highest_prev_bid > 0:
        # If opponents are bidding very high (e.g., > 110% of my salary), try to outbid them slightly
        if highest_prev_bid >= DAILY_SALARY * 1.1:
            bid = highest_prev_bid + 5.0
        # If opponents are bidding moderately, try to outbid them slightly but ensure a base
        else:
            bid = max(base_bid, highest_prev_bid + 1.0)
    else:
        # No previous bids or all were 0, use base bid
        bid = base_bid

    # Adjust bid based on remaining days and current budget for late-game aggression
    if day_context['day'] >= EPISODE_DAYS - 3: # Last 3 days, become more aggressive
        bid = max(bid, DAILY_SALARY * 0.9 + (EPISODE_DAYS - day_context['day']) * 2.0)

    # Ensure bid doesn't exceed budget and is at least 1
    return max(1.0, min(my_status['budget'], bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
