    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Collect yesterday's bids from opponents that have previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            yesterday_bids.append(trace['bid'])

    # If no opponents or no previous bids, use a default strategy
    if not yesterday_bids:
        # Conservative start: bid a portion of salary
        if my_hp <= 2:
            return min(my_budget, DAILY_SALARY * 0.9)
        else:
            return min(my_budget, DAILY_SALARY * 0.6)

    # Determine max opponent bid yesterday
    max_opp_bid = max(yesterday_bids)

    # Decide target bid based on our hp and opponent pressure
    if my_hp <= 2:
        # Desperate: need water, outbid yesterday's maximum slightly
        target = max_opp_bid + 1.0
    elif my_hp <= 5:
        # Moderate risk: try to match or slightly exceed
        target = max_opp_bid
    else:
        # Healthy: save money, bid low but not zero to ensure we get water if supply is high
        target = min(max_opp_bid * 0.7, DAILY_SALARY * 0.5)

    # Ensure we don't exceed budget and bid at least 0
    bid = max(0.0, min(my_budget, target))
    # Ensure integer index safety (though bid is float, not index)
    return bid

